"""Golden checks for the author's 5.1.2 rig. tests/golden/layout/author-512.json was generated by the code BEFORE the speaker-layout work
(commit "golden tests before the layout refactor"): the stimulus order and timing, the channel-ID stimulus, the profile model's output on a fixed
signal, and a complete simulated single-position run (proposals, verdict, table, room.proposed.json and, when set-eq.py is found, config.proposed.yml).
With the built-in 5.1.2 layout none of it may change. Floats are compared with a small tolerance so a different numpy build does not trip the test.
Regenerate only on purpose:  python3 tests/test_layout_golden.py --regen   (and say why in the commit).
Run: python3 tests/test_layout_golden.py   (needs numpy, scipy; about 10 s)
"""
import hashlib
import json
import os
import sys
import tempfile

from autocal_common import check, finish, fast_cfg, HERE

import numpy as np

from autocal import profile as PF, runner as RN, stimulus as ST
from autocal.sim.backend import SimBackend
from autocal.sim.room import SimRoom

GOLD = os.path.join(HERE, "golden", "layout", "author-512.json")
REGEN = "--regen" in sys.argv
TOL = 0.02


def canon(o):
    """JSON-able copy with numpy types converted and volatile run identifiers removed."""
    if isinstance(o, dict):
        return {str(k): canon(v) for k, v in o.items() if k not in ("id", "created", "run_dir", "path", "dir", "commands", "generated")}
    if isinstance(o, (list, tuple)):
        return [canon(v) for v in o]
    if isinstance(o, (np.floating, np.integer)):
        return o.item()
    return o


def same(a, b, path=""):
    """Returns '' when equal (floats within TOL), else the first difference."""
    if isinstance(a, dict) and isinstance(b, dict):
        if set(a) != set(b):
            return f"{path}: keys differ ({sorted(set(a) ^ set(b))[:5]})"
        for k in a:
            d = same(a[k], b[k], f"{path}.{k}")
            if d:
                return d
        return ""
    if isinstance(a, list) and isinstance(b, list):
        if len(a) != len(b):
            return f"{path}: length {len(a)} vs {len(b)}"
        for i, (x, y) in enumerate(zip(a, b)):
            d = same(x, y, f"{path}[{i}]")
            if d:
                return d
        return ""
    if isinstance(a, (int, float)) and isinstance(b, (int, float)) and not isinstance(a, bool) and not isinstance(b, bool):
        return "" if abs(a - b) <= TOL * max(1.0, abs(b) * 0.001 * 0 + 1.0) else f"{path}: {a} vs {b}"
    return "" if a == b else f"{path}: {a!r} vs {b!r}"


def snapshot():
    snap = {}
    tl = ST.Timeline(sweep_s=3.0, tail_s=1.5, level_db=-32.0)
    x = tl.render()
    snap["timeline_cues"] = canon(tl.cues)
    snap["timeline_shape"] = list(x.shape)
    snap["timeline_energy_db"] = [round(float(10 * np.log10(np.sum(x[:, c] ** 2) + 1e-20)), 2) for c in range(x.shape[1])]
    idx, cues = ST.id_stimulus(-40.0)
    snap["id_shape"] = list(idx.shape)
    snap["id_cues"] = canon(cues)
    snap["order"] = {"HW_ORDER": list(ST.HW_ORDER), "RESULT_ORDER": list(ST.RESULT_ORDER), "HEIGHTS": list(ST.HEIGHTS), "BED": list(ST.BED),
                     "BANDS": {k: list(v) for k, v in ST.BANDS.items()}, "BASS_CH": list(PF.BASS_CH)}
    rng = np.random.default_rng(7)
    sig = rng.standard_normal((9600, 8)) * 0.1
    y = PF.apply_profile(PF.default_room(), sig)
    snap["profile_model_rms_db"] = [round(float(10 * np.log10(np.mean(y[:, c] ** 2) + 1e-20)), 2) for c in range(y.shape[1])]
    with tempfile.TemporaryDirectory() as td:
        run = RN.Run(fast_cfg(td), SimBackend(room=SimRoom("default", seed=1)))
        run.run()
        res = json.load(open(os.path.join(run.dir, "results.json")))
        snap["results"] = canon(res)
        snap["room_proposed"] = canon(json.load(open(os.path.join(run.dir, "room.proposed.json"))))
        cp = os.path.join(run.dir, "config.proposed.yml")
        snap["config_proposed_sha256"] = hashlib.sha256(open(cp, "rb").read()).hexdigest() if os.path.exists(cp) else None
        snap["report_has_all_channels"] = all(n in open(os.path.join(run.dir, "report.html")).read() for n in ST.RESULT_ORDER)
    return snap


snap = snapshot()
if REGEN:
    os.makedirs(os.path.dirname(GOLD), exist_ok=True)
    with open(GOLD, "w") as fh:
        json.dump(snap, fh, indent=1, sort_keys=True)
        fh.write("\n")
    print("wrote", GOLD)
    sys.exit(0)

gold = json.load(open(GOLD))
for key in sorted(gold):
    if key == "config_proposed_sha256":
        if gold[key] is None or snap[key] is None:
            check("config.proposed.yml: skipped (set-eq.py not found here or when the golden file was made)", True)
        else:
            check("config.proposed.yml for the simulated run is byte-identical to the one made before the layout work", snap[key] == gold[key])
        continue
    d = same(snap.get(key), gold[key], key)
    check(f"golden {key} unchanged for the 5.1.2 layout", not d, d)
finish("layout golden (author 5.1.2)")
